STYLE='''*{box-sizing:border-box}body{font:17px/1.6 Georgia,"Noto Serif",serif;color:#243248;margin:auto;max-width:1140px;padding:40px 25px;background:#fafaf8}h1,h2,h3,summary,th{font-family:system-ui,sans-serif}h1{font-size:32px}h2{margin-top:2em;border-bottom:1px solid #d9dfe5;padding-bottom:.4em}a{color:#176c9c}table{border-collapse:collapse;width:100%;margin:20px 0;font-size:15px}td,th{overflow-wrap:anywhere;border-bottom:1px solid #dce1e5;padding:8px;text-align:left;vertical-align:top}th{background:#edf2f5}code,pre,.equation{font-family:ui-monospace,monospace;font-size:14px;overflow-wrap:anywhere}pre{white-space:pre-wrap}.equation{background:#edf2f5;padding:16px}summary{cursor:pointer;padding:12px;background:#edf2f5}details{margin:14px 0;border:1px solid #dce1e5;border-radius:5px;padding:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}.card{padding:12px;border:1px solid #dce1e5;background:white}.card svg{max-width:420px;width:100%}.tag{font:13px system-ui;color:#176c9c}.muted{color:#667}.warning{background:#fff1d9;padding:14px}svg{max-width:420px;width:100%;height:auto}.reading-guide{border-left:4px solid #176c9c;padding:2px 18px;background:#edf2f5}.table-wrap{overflow-x:auto;max-width:100%;min-width:0}.grid>*{min-width:0}.jump-links{display:flex;flex-wrap:wrap;gap:14px}.gauss-diagram{display:block} .case-description{background:#f1f5f8;padding:12px} @media(max-width:600px){body{padding:22px 12px}h1{font-size:26px}.grid{grid-template-columns:1fr}td,th{padding:6px}}button{cursor:pointer;padding:8px 14px;border:1px solid #c4cdd5;border-radius:4px;background:white}@media print{details{break-inside:avoid}body{max-width:none;padding:0}button{display:none}}'''
